import React, { useEffect, useState } from 'react';
import axios from 'axios';

const App = () => {
  const [expenses, setExpenses] = useState([]);
  const [form, setForm] = useState({ name: '', amount: '', date: '', category: 'Food' });

  const fetchExpenses = async () => {
    const res = await axios.get('http://localhost:5000/api/expenses');
    setExpenses(res.data);
  };

  useEffect(() => {
    fetchExpenses();
  }, []);

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const addExpense = async () => {
    if (!form.name || !form.amount || !form.date) return alert('Fill all fields');
    await axios.post('http://localhost:5000/api/expenses', form);
    setForm({ name: '', amount: '', date: '', category: 'Food' });
    fetchExpenses();
  };

  const deleteExpense = async id => {
    await axios.delete(`http://localhost:5000/api/expenses/${id}`);
    fetchExpenses();
  };

  return (
    <div className="container">
      <h2>Expense Tracker</h2>
      <input name="name" placeholder="Name" value={form.name} onChange={handleChange} />
      <input name="amount" type="number" placeholder="Amount" value={form.amount} onChange={handleChange} />
      <input name="date" type="date" value={form.date} onChange={handleChange} />
      <select name="category" value={form.category} onChange={handleChange}>
        <option>Food</option>
        <option>Transport</option>
        <option>Shopping</option>
        <option>Entertainment</option>
        <option>Health</option>
        <option>Education</option>
        <option>Bills</option>
        <option>Other</option>
      </select>
      <button onClick={addExpense}>Add Expense</button>
      <ul>
        {expenses.map(e => (
          <li key={e._id}>
            <span>{e.name} - ₹{e.amount} ({e.category}) on {e.date}</span>
            <button onClick={() => deleteExpense(e._id)}>X</button>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default App;
